sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    g_form.clearMessages(); // Clears all previous messages
    var ga = new GlideAjax('BasesUtils');
    ga.addParam('sysparm_name', 'checkManagerBase');
    ga.addParam('sysparm_manager', g_form.getValue('base_manager'));

    ga.getXMLAnswer(function(answer) {
        if (answer && answer !== 'none') {
            var msg = 'This Manager ' + g_form.getDisplayValue('base_manager') + ' was already assigned to a Base before.';

            g_form.addErrorMessage(msg);
            g_form.clearValue('base_manager');

        }

    });
}
